2|
3|namespace App\Services;
4|
5|use Carbon\Carbon;
6|use Illuminate\Database\Eloquent\Builder as EloquentBuilder;
7|use Illuminate\Database\Eloquent\Model;
8|use Illuminate\Database\Query\Builder as QueryBuilder;
9|use Illuminate\Support\Facades\DB;
10|
11|/**
12| * Daily counts over a date window, with the days that have no rows present as
13| * zero (issue #736).
14| *
15| * A `GROUP BY date(...)` aggregate only returns days that exist in the table, so
16| * a day with no tickets becomes a missing column — which reads as "no data"
17| * rather than "zero that day". Here the window is materialised with
18| * `generate_series` and left-joined against the aggregate, so the shape of the
19| * output depends only on the window, never on how the data happens to be
20| * distributed.
21| *
22| * Deliberately not read from `daily_reports`: that table is written by
23| * `reports:generate-daily` at 06:00, so it is always a day behind, and a failed
24| * schedule silently becomes a hole in the chart.
25| */
26|class DailySeries
27|{
28|    public const DEFAULT_DAYS = 30;
29|
30|    public const MAX_DAYS = 365;
31|
32|    public function __construct(
33|        private readonly int $days = self::DEFAULT_DAYS,
34|        private readonly ?Carbon $from = null,
35|        private readonly ?Carbon $to = null,
36|    ) {}
37|
38|    /**
39|     * The last N days, ending today (inclusive). `days = 1` is today alone.
40|     *
41|     * This is the `?days=` path (`/api/reports/*`, the dashboard trend): there is
42|     * no picked range, so the window is derived from `now()`.
43|     */
44|    public static function lastDays(int $days): self
45|    {
46|        // `now()` is a CarbonInterface; `Carbon::instance()` is the documented
47|        // narrowing (Carbon ≥ 3), so the stored bounds are plain Carbon.
48|        $to = Carbon::instance(now()->startOfDay());
49|
50|        return new self($days, $to->copy()->subDays($days - 1), $to);
51|    }
52|
53|    /**
54|     * An explicit inclusive range — for pages that already offer a
55|     * date-from/date-to picker and therefore have no single "last N days".
56|     *
57|     * The range itself is kept, because it *is* the contract: previously only the
58|     * day count survived and `window()` rebuilt "N days ending today", so every
59|     * past window charted the wrong axis and `counts()`' LEFT JOIN dropped the
60|     * rows that sat inside the range the user actually picked (issue #866).
61|     *
62|     * A range wider than MAX_DAYS is clamped back to MAX_DAYS ending on the
63|     * picked to-day. `?days=` is already rejected above the cap by `ReportDays`,
64|     * but a picker page takes free-text Jalali dates straight through, and an
65|     * unclamped 40-year range materialises 14610 rows — one Highcharts point each.
66|     */
67|    public static function between(Carbon $from, Carbon $to): self
68|    {
69|        $start = $from->copy()->startOfDay();
70|        $end = $to->copy()->startOfDay();
71|
72|        if ($start->gt($end)) {
73|            [$start, $end] = [$end, $start];
74|        }
75|
76|        $days = (int) $start->diffInDays($end) + 1;
77|
78|        if ($days > self::MAX_DAYS) {
79|            $start = $end->copy()->subDays(self::MAX_DAYS - 1);
80|            $days = self::MAX_DAYS;
81|        }
82|
83|        return new self($days, $start, $end);
84|    }
85|
86|    /**
87|     * Resolve a raw `?days=` value.
88|     *
89|     * A missing or non-numeric value falls back to the default rather than
90|     * erroring, so a sloppy `?days=abc` still renders a chart. Numeric values
91|     * outside 1..MAX are returned as-is and rejected by the validator, so the
92|     * client is told why instead of silently getting a different window.
93|     */
94|    public static function resolveDays(mixed $value): int
95|    {
96|        if ($value === null || $value === '' || ! is_numeric($value)) {
97|            return self::DEFAULT_DAYS;
98|        }
99|
100|        return (int) $value;
101|    }
102|
103|    /**
104|     * Counts per day over the window, ascending, one entry per day.
105|     *
106|     * `$query` is the caller's own already-filtered builder — unit scope, status
107|     * filter, whatever the page needs — so this fills gaps in an existing
108|     * aggregate instead of re-deriving its filters. A query that matches nothing
109|     * yields a full-length window of zeros, never a shorter one.
110|     *
111|     * Accepts either builder flavour; the helpers below narrow down what each
112|     * path needs, so neither case is handled twice.
113|     *
114|     * @param  EloquentBuilder<covariant Model>|QueryBuilder  $query
115|     * @return array<int, array{day: string, count: int}> Gregorian `Y-m-d` days.
116|     */
117|    public function counts(EloquentBuilder|QueryBuilder $query, string $dateColumn): array
118|    {
119|        [$from, $to] = $this->window();
120|
121|        $grammar = DB::connection()->getQueryGrammar();
122|        $wrappedDate = $grammar->wrap($this->qualifiedColumn($query, $dateColumn));
123|
124|        // The aggregate is a subquery built from the caller's builder, so all of
125|        // its filters and bindings are preserved. Identifiers are code
126|        // constants, never request input; the window is bound as two dates.
127|        $perDay = $this->toBaseQuery($query)
128|            ->selectRaw("date({$wrappedDate}) as day, COUNT(*) as count")
129|            ->groupByRaw("date({$wrappedDate})");
130|
131|        $rows = DB::select(
132|            'WITH days AS (
133|                SELECT generate_series(?::date, ?::date, interval \'1 day\')::date AS day
134|             )
135|             SELECT days.day::text AS day, COALESCE(per_day.count, 0) AS count
136|             FROM days
137|             LEFT JOIN ('.$perDay->toSql().') AS per_day ON per_day.day = days.day
138|             ORDER BY days.day',
139|            array_merge([$from, $to], $perDay->getBindings())
140|        );
141|
142|        return array_map(fn ($row) => [
143|            'day' => (string) $row->day,
144|            'count' => (int) $row->count,
145|        ], $rows);
146|    }
147|
148|    /**
149|     * The window as Gregorian `Y-m-d` bounds, oldest first — the range itself,
150|     * not a recomputed one.
151|     *
152|     * @return array{0: string, 1: string}
153|     */
154|    public function window(): array
155|    {
156|        $to = $this->to ?? now()->startOfDay();
157|        $from = $this->from ?? $to->copy()->subDays($this->days - 1);
158|
159|        return [$from->copy()->startOfDay()->toDateString(), $to->copy()->startOfDay()->toDateString()];
160|    }
161|
162|    /**
163|     * Table-qualify the date column when the builder knows its model, so a
164|     * joined aggregate cannot resolve the bare name to the wrong table.
165|     *
166|     * @param  EloquentBuilder<covariant Model>|QueryBuilder  $query
167|     */
168|    private function qualifiedColumn(EloquentBuilder|QueryBuilder $query, string $dateColumn): string
169|    {
170|        if (! $query instanceof EloquentBuilder) {
171|            return $dateColumn;
172|        }
173|
174|        return $query->getModel()->getTable().'.'.$dateColumn;
175|    }
176|
177|    /**
178|     * The underlying base builder — a clone, so adding the group-by never
179|     * mutates the caller's query.
180|     *
181|     * @param  EloquentBuilder<covariant Model>|QueryBuilder  $query
182|     */
183|    private function toBaseQuery(EloquentBuilder|QueryBuilder $query): QueryBuilder
184|    {
185|        return clone ($query instanceof EloquentBuilder ? $query->toBase() : $query);
186|    }
