3|namespace App\Services;
4|
5|use App\Models\Unit;
6|use App\Models\User;
7|use Illuminate\Support\Facades\Cache;
8|
9|class AccessService
10|{
11|    /**
12|     * واحدهای قابل دسترس کاربر (شامل خودش + تمام زیرمجموعه‌ها)
13|     *
14|     * @return array<int>
15|     */
16|    public function accessibleUnitIds(?User $user = null): array
17|    {
18|        $user ??= auth()->user();
19|
20|        if (! $user) {
21|            return [];
22|        }
23|
24|        $currentUnitId = session('current_unit_id');
25|
26|        if ($currentUnitId) {
27|            $baseUnitIds = [$currentUnitId];
28|        } else {
29|            $baseUnitIds = $user->units()->pluck('units.id')->toArray();
30|
31|            if (empty($baseUnitIds)) {
32|                $personUnitId = $user->person?->u_id;
33|                if ($personUnitId) {
34|                    $baseUnitIds = [$personUnitId];
35|                }
36|            }
37|        }
38|
39|        if (empty($baseUnitIds)) {
40|            return [];
41|        }
42|
43|        $sessionUnitId = session('current_unit_id', 'none');
44|        $cache = app(CacheInvalidationServiceInterface::class);
45|        $version = $cache->getVersion('unit_hierarchy');
46|        $sortedBase = $baseUnitIds;
47|        sort($sortedBase);
48|        $cacheKey = "accessible_units:v{$version}:{$user->id}:{$sessionUnitId}:".md5(json_encode($sortedBase));
49|
50|        return Cache::remember(
51|            $cacheKey,
52|            now()->addMinutes(30),
53|            fn () => Unit::descendantIds($baseUnitIds)->toArray()
54|        );
55|    }
56|
57|    /**
58|     * تمام واحدهای سازمان، بدون وابستگی به کاربر یا نشست جاری
59|     *
60|     * `accessibleUnitIds()` به `auth()` و `session()` وابسته است، پس در
61|     * scheduler یا queue worker همیشه `[]` برمی‌گرداند و هر مصرف‌کننده‌ای
62|     * آن را «کاری برای انجام نیست» می‌خواند. نگهداشت داده (retention) و
63|     * تولید گزارش وظیفه سراسری‌اند، نه وابسته به اینکه چه کسی دکمه را
64|     * زده — وگرنه دو مدیر با دامنه‌های متفاوت دو برش متفاوت از یک جدول را
65|     * پاک می‌کردند. این متد جایگزین آن است، نه مکملش.
66|     *
67|     * عمداً بدون کش: یک کوئری ساده در مسیرهای کم‌تکرار (زمان‌بند و worker)
68|     * و بدون نیاز به نسخه‌بندی کش جدید در `PruneStaleCache::NAMESPACES`.
69|     *
70|     * @return array<int>
71|     */
72|    public function allUnitIds(): array
73|    {
74|        return Unit::query()
75|            ->get(['id'])
76|            ->map(fn (Unit $unit): int => $unit->id)
77|            ->all();
78|    }
79|
80|    /**
81|     * پاک کردن کش دسترسی کاربر (هنگام تغییر context یا تغییر واحدها)
82|     */
83|    public function clearCache(?User $user = null): void
84|    {
85|        $user ??= auth()->user();
86|
87|        if ($user) {
88|            // Bump the version counter so ANY versioned accessible_units key for this
89|            // hierarchy (including keys written under an older version) becomes
90|            // unreachable instead of surviving until TTL (fix for stale-cache bug).
91|            $cache = app(CacheInvalidationServiceInterface::class);
92|            $cache->increment('unit_hierarchy');
93|
94|            $currentUnitId = session('current_unit_id');
95|            $sessionUnitId = session('current_unit_id', 'none');
96|            $baseUnitIds = $currentUnitId
97|                ? [$currentUnitId]
98|                : $user->units()->pluck('units.id')->toArray();
99|
100|            // Forget the legacy unversioned key too.
101|            $cacheKey = "accessible_units:{$user->id}:{$sessionUnitId}:".md5(json_encode($baseUnitIds));
102|            Cache::forget($cacheKey);
103|        }
104|    }
105|
106|    /**
107|     * پاک کردن تمام کش‌های دسترسی (هنگام تغییر سلسله‌مراتب واحدها)
108|     */
109|    public function clearAllCaches(): void
110|    {
111|        $cache = app(CacheInvalidationServiceInterface::class);
112|        $cache->increment('unit_hierarchy');
113|        $cache->increment('gis');
114|    }
