91|    private function snapshotNCode(HardwareAudit $audit): ?string
92|    {
93|        $changes = $audit->changes;
94|
95|        if (empty($changes)) {
96|            return null;
97|        }
98|
99|        foreach ($changes as $change) {
100|            if (($change['field'] ?? null) === 'n_code' && isset($change['new'])) {
101|                return is_string($change['new']) && $change['new'] !== '—' ? $change['new'] : null;
102|            }
103|        }
104|
105|        return null;
106|    }
