56|                                 WHERE p.r_id IS NOT NULL AND p.u_id = ANY(?) GROUP BY p.r_id, r.name) x) AS by_radif",
57|                    [$idArray, $idArray, $idArray, $idArray, $idArray, $idArray]
58|                );
59|
60|                return [
