174|     */
175|    public function personDetail(UnitScopedRequest $request, string $nCode): JsonResponse
176|    {
177|        $accessibleIds = $request->accessibleIds();
178|
179|        $person = Person::with(['unit:id,name', 'semat:id,name', 'tahsil:id,name', 'estekhdam:id,name', 'radif:id,name'])
