139|                    return [
140|                        'id' => $unit->id,
141|                        'name' => $unit->name,
142|                        'parent_id' => $unit->parent_id,
143|                        'unit_type' => $unit->unitType?->name,
144|                        'personnel_count' => $unit->personnel_count,
145|                        'has_children' => $childUnits->isNotEmpty(),
146|                        'children' => $childUnits->map(fn (Unit $c) => $format($c))->values(),
147|                    ];
148|                };
149|
150|                return collect($children)->map(fn (Unit $c) => $format($c))->values();
151|            }, 10, ['subtree' => $unitId]);
152|
