18|
19|    public function __construct(
20|        protected CacheInvalidationServiceInterface $cache
21|    ) {}
22|
23|    /**
24|     * Apply bbox spatial filter using lat/lng columns (works without geom column).
25|     */
26|    protected function applyBbox($query, UnitScopedRequest $request)
27|    {
28|        if (! $request->filled('bbox')) {
29|            return $query;
30|        }
31|
32|        $bbox = explode(',', $request->bbox);
33|        if (count($bbox) !== 4) {
34|            return $query;
35|        }
36|
37|        [$minLon, $minLat, $maxLon, $maxLat] = array_map('floatval', $bbox);
38|
39|        $query->whereBetween('lat', [$minLat, $maxLat])
40|            ->whereBetween('lng', [$minLon, $maxLon]);
41|
42|        return $query;
43|    }
44|
45|    /**
46|     * Bbox filter for queries with prefixed/aliased columns (JOINs) — Issue #404.
47|     */
48|    protected function applyBboxAliased($query, UnitScopedRequest $request)
49|    {
50|        if (! $request->filled('bbox')) {
51|            return $query;
52|        }
53|
54|        $bbox = explode(',', $request->bbox);
55|        if (count($bbox) !== 4) {
56|            return $query;
57|        }
58|
59|        [$minLon, $minLat, $maxLon, $maxLat] = array_map('floatval', $bbox);
60|
61|        $query->whereBetween('units.lat', [$minLat, $maxLat])
62|            ->whereBetween('units.lng', [$minLon, $maxLon]);
63|
64|        return $query;
65|    }
