109|    /**
110|     * Get units as GeoJSON FeatureCollection within spatial bounds.
111|     * Query params: bbox (minLon,minLat,maxLon,maxLat)
112|     */
113|    public function units(UnitScopedRequest $request): JsonResponse
114|    {
115|        $accessibleIds = $request->accessibleIds();
116|        $bbox = $this->normalizedBbox($request);
117|        $cacheKey = $this->gisCacheKey('units', $accessibleIds, $bbox);
118|
119|        $features = Cache::remember($cacheKey, now()->addMinutes(60), function () use ($accessibleIds, $request) {
120|            $query = Unit::whereIn('id', $accessibleIds)
121|                ->whereNotNull('lat')
122|                ->whereNotNull('lng')
123|                ->select('id', 'name', 'unit_type_id', 'parent_id', 'region_id', 'lat', 'lng');
124|
