129|            return $units->map(function ($unit) {
130|                return [
131|                    'type' => 'Feature',
132|                    'id' => $unit->id,
133|                    'geometry' => [
134|                        'type' => 'Point',
135|                        'coordinates' => [(float) $unit->lng, (float) $unit->lat],
136|                    ],
137|                    'properties' => [
138|                        'id' => $unit->id,
139|                        'name' => $unit->name,
140|                        'unit_type_id' => $unit->unit_type_id,
141|                        'parent_id' => $unit->parent_id,
