316|    public function stats(UnitScopedRequest $request): JsonResponse
317|    {
318|        $accessibleIds = $request->accessibleIds();
319|        $bbox = $this->normalizedBbox($request);
320|        $cacheKey = $this->gisCacheKey('stats', $accessibleIds, $bbox);
321|
322|        $data = Cache::remember($cacheKey, now()->addMinutes(60), function () use ($accessibleIds, $request) {
323|            // Build bbox conditions once and reuse across all three counts (#402)
