2|
3|namespace App\Http\Controllers\Api;
4|
5|use App\Http\Controllers\Controller;
6|use App\Services\Zabbix\ZabbixClient;
7|use Illuminate\Http\JsonResponse;
8|use Illuminate\Http\Request;
9|use Illuminate\Support\Facades\Cache;
10|use Illuminate\Support\Facades\Log;
11|use Throwable;
12|
13|class TrafficController extends Controller
14|{
15|    public function index(Request $request, ZabbixClient $zabbix)
16|    {
17|        $validated = $request->validate([
18|            'out_item_id' => 'required',
19|            'in_item_id' => 'required',
20|            'duration' => 'nullable|integer|min:60|max:86400',
21|        ]);
22|
23|        $outItemId = $validated['out_item_id'];
24|        $inItemId = $validated['in_item_id'];
25|        $duration = $validated['duration'] ?? 3600;
26|
27|        try {
28|            $cacheKey = "traffic_{$outItemId}_{$inItemId}_{$duration}";
29|
30|            // #764: read the per-request cache back — it used to be a
31|            // write-only key while EVERY request was short-circuited by the
32|            // sync job's `zabbix_traffic_data` (default config items, wrong
33|            // `['data' => ...]` shape) regardless of the requested item IDs.
34|            // The job's cache stays for the dashboard banner (`Cache::has`),
35|            // but the controller must not serve another request's data.
36|            $data = Cache::get($cacheKey);
37|
38|            if ($data === null) {
39|                // #741: the transport now returns a typed result instead of
40|                // throwing; the mapping below (connection problem -> 503 with the
41|                // exact same body) is the contract the existing tests pin.
42|                $out = $zabbix->traffic($outItemId, $duration);
43|
44|                if ($out->failed()) {
45|                    return $this->unavailable('out', $out->failure(), $out->message());
46|                }
47|
48|                $in = $zabbix->traffic($inItemId, $duration);
49|
50|                if ($in->failed()) {
51|                    return $this->unavailable('in', $in->failure(), $in->message());
52|                }
53|
54|                $data = [
55|                    'out' => $out->data(),
56|                    'in' => $in->data(),
57|                ];
58|
59|                Cache::put($cacheKey, $data, 30);
60|            }
61|
62|            return response()->json($data);
63|        } catch (Throwable $e) {
64|            Log::error('Zabbix Traffic API error', ['exception' => $e]);
65|
66|            return response()->json(['error' => 'Service temporarily unavailable'], 503);
67|        }
68|    }
69|
70|    /**
71|     * The unchanged 503 contract, reached through a typed failure (#741):
72|     * same body, same status, only the log now carries the failure kind.
73|     */
74|    protected function unavailable(string $side, ?string $failure, ?string $message): JsonResponse
75|    {
76|        Log::error('Zabbix Traffic API error', [
77|            'side' => $side,
78|            'failure' => $failure,
79|            'message' => $message,
80|        ]);
81|
82|        return response()->json(['error' => 'Service temporarily unavailable'], 503);
83|    }
