2|
3|namespace App\Observers;
4|
5|use App\Models\Hardware;
6|use App\Models\HardwareAudit;
7|use Illuminate\Support\Facades\Auth;
8|
9|class HardwareAuditObserver
10|{
11|    /**
12|     * Check if audit logging should be suppressed.
13|     *
14|     * Supports both static flag (standard PHP-FPM) and request attributes
15|     * (Laravel Octane / long-running workers).
16|     */
17|    protected function shouldSuppress(): bool
18|    {
19|        return Hardware::$suppressAudit
20|            || request()->attributes->get('suppress_audit', false);
21|    }
22|
23|    /**
24|     * Handle the Hardware "created" event.
25|     */
26|    public function created(Hardware $hardware): void
27|    {
28|        if ($this->shouldSuppress()) {
29|            return;
30|        }
31|
32|        $fields = [
33|            'n_code', 'pc_name', 'type', 'os', 'cpu', 'ram', 'hdd', 'net_type',
34|            'switch', 'port', 'vlan', 'motherboard', 'comments',
35|            'ip_valid', 'ip_local', 'mac', 'shutdown', 'mark', 'clean_at',
36|        ];
37|        $changes = [];
38|        foreach ($fields as $field) {
39|            $value = $hardware->getAttribute($field);
40|            if ($value !== null && $value !== '') {
41|                $changes[] = [
42|                    'field' => $field,
43|                    'old' => '—',
44|                    'new' => $this->formatValueForDisplay($value),
45|                ];
46|            }
47|        }
48|        $this->recordAudit($hardware, 'created', $changes ?: null, $this->detectSource());
49|    }
50|
51|    /**
52|     * Handle the Hardware "updated" event.
53|     *
54|     * We use `updating` (fires BEFORE the model syncs its changes)
55|     * because in `updated` the dirty attributes are already cleared.
56|     */
57|    public function updating(Hardware $hardware): void
58|    {
59|        if ($this->shouldSuppress()) {
60|            return;
61|        }
62|
63|        $changes = $this->getChangedFields($hardware);
64|
65|        if (! empty($changes)) {
66|            $this->recordAudit($hardware, 'updated', $changes, $this->detectSource());
67|        }
68|    }
69|
70|    /**
71|     * Handle the Hardware "deleted" event.
72|     */
73|    public function deleting(Hardware $hardware): void
74|    {
75|        if ($this->shouldSuppress()) {
76|            return;
77|        }
78|
79|        $hardwareId = $hardware->id;
80|        $this->recordAudit($hardware, 'deleted', null, $this->detectSource(), $hardwareId);
81|    }
82|
83|    /**
84|     * Handle the Hardware "forceDeleted" event.
85|     */
86|    public function forceDeleted(Hardware $hardware): void
87|    {
88|        if ($this->shouldSuppress()) {
89|            return;
90|        }
91|
92|        $this->recordAudit($hardware, 'force_deleted', null, $this->detectSource());
93|    }
94|
95|    /**
96|     * Record a bulk operation audit entry (bulk_mark / bulk_delete).
97|     * Used by the API controller for bulk actions so each affected
98|     * hardware record gets its own audit row.
99|     */
100|    public function recordBulkAudit(Hardware $hardware, string $action, ?array $changes): void
101|    {
102|        $this->recordAudit($hardware, $action, $changes, 'bulk');
103|    }
104|
105|    /**
106|     * Record a rollback audit entry (creates a new audit row for traceability).
107|     */
108|    public function recordRollbackAudit(Hardware $hardware, array $rollbackChanges, ?int $userId = null): void
109|    {
110|        HardwareAudit::create([
111|            'hardware_id' => $hardware->id,
112|            'user_id' => $userId ?? Auth::id(),
113|            'action' => 'rollback',
114|            'changes' => $rollbackChanges,
115|            'source' => $this->detectSource(),
116|            'ip_address' => request()?->ip(),
117|            'user_agent' => request()?->userAgent(),
118|        ]);
119|    }
120|
121|    /**
122|     * Detect the source of the change (web, api, import, bulk).
123|     */
124|    protected function detectSource(): string
125|    {
126|        $route = request()->route();
127|
128|        if ($route && $route->getName() === 'hardware.import') {
129|            return 'import';
130|        }
131|
132|        if ($route && str_starts_with($route->uri(), 'api/')) {
133|            return 'api';
134|        }
135|
136|        return 'web';
137|    }
138|
139|    /**
140|     * Record an audit entry for the hardware.
141|     */
142|    protected function recordAudit(Hardware $hardware, string $action, ?array $changes, string $source, ?int $hardwareId = null): void
143|    {
144|        $user = Auth::user();
145|        $request = request();
146|
147|        HardwareAudit::create([
148|            'hardware_id' => $hardwareId ?? $hardware->id,
149|            'user_id' => $user?->id,
150|            'action' => $action,
151|            'changes' => $changes,
152|            'source' => $source,
153|            'ip_address' => $request?->ip(),
154|            'user_agent' => $request?->userAgent(),
155|        ]);
156|    }
157|
158|    /**
159|     * Get changed fields with old and new values.
160|     */
161|    protected function getChangedFields(Hardware $hardware): array
162|    {
163|        $dirty = $hardware->getDirty();
164|        $original = $hardware->getOriginal();
165|
166|        $changes = [];
167|
168|        foreach ($dirty as $field => $newValue) {
169|            // Ignore auto-managed timestamp fields
170|            if (in_array($field, ['updated_at', 'created_at'], true)) {
171|                continue;
172|            }
173|
174|            // Use array_key_exists so null→value transitions are captured
175|            $oldValue = array_key_exists($field, $original) ? $original[$field] : null;
176|
177|            // Normalize values for comparison
178|            $normalizedOld = $this->normalizeValue($oldValue);
179|            $normalizedNew = $this->normalizeValue($newValue);
180|
181|            if ($normalizedOld !== $normalizedNew) {
182|                $changes[] = [
183|                    'field' => $field,
184|                    'old' => $this->formatValueForDisplay($oldValue),
185|                    'new' => $this->formatValueForDisplay($newValue),
186|                ];
187|            }
188|        }
189|
190|        return $changes;
191|    }
192|
193|    /**
194|     * Normalize a value for comparison.
195|     */
196|    protected function normalizeValue(mixed $value): string
197|    {
198|        if ($value === null) {
199|            return '';
200|        }
201|        if (is_bool($value)) {
202|            return $value ? '1' : '0';
203|        }
204|
205|        return (string) $value;
206|    }
207|
208|    /**
209|     * Format a value for display in the changes log.
210|     */
211|    protected function formatValueForDisplay(mixed $value): string
212|    {
213|        if ($value === null) {
214|            return '—';
215|        }
216|        if (is_bool($value)) {
217|            return $value ? 'بله' : 'خیر';
218|        }
219|        if (is_array($value)) {
220|            return json_encode($value, JSON_UNESCAPED_UNICODE);
221|        }
222|
223|        return (string) $value;
224|    }
