36|        'semat' => ['label' => 'سمت'],
37|        'tahsil' => ['label' => 'تحصیلات'],
38|        'estekhdam' => ['label' => 'نوع استخدام'],
39|        'radif' => ['label' => 'ردیف سازمانی'],
40|        'unit' => ['label' => 'واحد سازمانی'],
41|        'status' => ['label' => 'وضعیت'],
42|        'birth_date' => ['label' => 'تاریخ تولد'],
43|        'hire_date' => ['label' => 'تاریخ استخدام'],
44|    ];
45|
