47|    protected array $columns = [
48|        'n_code', 'f_name', 'l_name', 'full_name', 'semat', 'tahsil',
49|        'estekhdam', 'radif', 'unit', 'status', 'birth_date', 'hire_date',
50|    ];
51|
52|    /** @var Collection<int, Person> */
53|    protected Collection $persons;
54|
55|    /**
56|     * Breadcrumb walker from the shared unit tree service (#756) — the same
57|     * chain the tree UI and the units export resolve their hierarchy with.
58|     */
59|    protected UnitTreeService $unitTree;
60|
61|    /**
62|     * Every unit keyed by id with `parent` linked in memory, built once on
63|     * first row so mapping never walks back to the database.
64|     *
65|     * @var array<int, Unit>|null
66|     */
67|    protected ?array $unitsById = null;
