74|    }
75|
76|    /**
77|     * @return Collection<int, Person>
78|     */
79|    public function collection(): Collection
80|    {
81|        return $this->persons;
82|    }
83|
84|    public function headings(): array
85|    {
86|        return array_map(
87|            fn (string $key) => $this->columnDefs[$key]['label'],
88|            $this->columns
89|        );
90|    }
91|
92|    /**
93|     * @param  Person  $person
94|     */
95|    public function map($person): array
96|    {
97|        return array_map(
98|            fn (string $key) => $this->resolveValue($person, $key),
99|            $this->columns
100|        );
101|    }
102|
103|    protected function resolveValue(Person $person, string $key): mixed
104|    {
105|        return match ($key) {
106|            'full_name' => $this->resolveFullName($person),
107|            'semat' => $person->semat->name ?? '-',
108|            'tahsil' => $person->tahsil->name ?? '-',
109|            'estekhdam' => $person->estekhdam->name ?? '-',
110|            'radif' => $person->radif->name ?? '-',
111|            'unit' => $this->resolveUnitPath($person),
112|            'status' => $this->resolveStatus($person),
113|            'birth_date' => $this->resolveJalaliDate($person->birth_date),
114|            'hire_date' => $this->resolveJalaliDate($person->hire_date),
115|            default => (string) ($person->{$key} ?? '-'),
116|        };
117|    }
118|
119|    /**
120|     * `Person::$name` falls back to «—» when both name parts are blank, which
121|     * is a UI affordance, not a name. The sheet gets a dash instead.
122|     */
123|    protected function resolveFullName(Person $person): string
124|    {
125|        $name = trim("{$person->f_name} {$person->l_name}");
126|
127|        return $name !== '' ? $name : '-';
128|    }
129|
130|    protected function resolveJalaliDate(?Carbon $date): string
131|    {
132|        return $date !== null ? Jalalian::fromCarbon($date)->format('Y/m/d') : '-';
133|    }
134|
135|    /**
136|     * The person's unit as the full breadcrumb — the same contract as the
137|     * units export's «مسیر کامل» column (#756): every ancestor names the
138|     * path, joined with ' > ', and ancestors above the caller's scope still
139|     * appear (the tree page renders those, so nothing new leaks). Walking
140|     * `UnitTreeService::ancestorChain()` over the in-memory index keeps the
141|     * guarantee the class docblock makes: mapping a row never queries.
142|     * A person whose unit is missing or gone reports '-' like every other
143|     * absent cell in this sheet.
144|     */
145|    protected function resolveUnitPath(Person $person): string
146|    {
147|        $units = $this->unitsById();
148|        $unit = $units[(int) $person->u_id] ?? null;
149|
150|        if (! $unit instanceof Unit) {
151|            return '-';
152|        }
153|
154|        $chain = $this->unitTree->ancestorChain($unit, array_keys($units));
155|
156|        return $chain->pluck('name')->push($unit->name)->implode(' > ');
157|    }
158|
159|    /**
160|     * All units keyed by id, with each `parent` relation pre-linked in
161|     * memory. One query per export, not one per row or per hop — the same
162|     * shape UnitsExportController's `hierarchyMap()` gives the units
163|     * breadcrumb. The index deliberately covers every unit, not just the
164|     * caller's scope, so `ancestorChain()` walks to the real root.
165|     *
166|     * @return array<int, Unit>
167|     */
168|    protected function unitsById(): array
169|    {
170|        if ($this->unitsById !== null) {
171|            return $this->unitsById;
172|        }
173|
174|        /** @var array<int, Unit> $units */
175|        $units = [];
176|
177|        foreach (Unit::query()->get(['id', 'name', 'parent_id']) as $unit) {
178|            $units[(int) $unit->id] = $unit;
179|        }
180|
181|        foreach ($units as $unit) {
182|            if ($unit->parent_id !== null) {
183|                // A parent_id pointing outside the index (impossible under
184|                // the FK, guarded anyway) ends the chain instead of exploding.
185|                $unit->setRelation('parent', $units[(int) $unit->parent_id] ?? null);
186|            }
187|        }
188|
189|        return $this->unitsById = $units;
190|    }
191|
192|    /**
193|     * `persons.status` is a plain string column (active | inactive | retired).
194|     * An empty or unknown value reports the absence, never a guess.
195|     */
196|    protected function resolveStatus(Person $person): string
197|    {
198|        return match ($person->status) {
199|            'active' => 'فعال',
200|            'inactive' => 'غیرفعال',
201|            'retired' => 'بازنشسته',
202|            default => '-',
203|        };
204|    }
205|
206|    public function title(): string
207|    {
208|        return 'پرسنل';
209|    }
210|
211|    /**
212|     * @return array<string, callable>
213|     */
214|    public function registerEvents(): array
215|    {
216|        return [
217|            // Persian sheet: first column renders on the right, like the app UI.
218|            AfterSheet::class => function (AfterSheet $event): void {
219|                $event->sheet->getDelegate()->setRightToLeft(true);
220|            },
221|        ];
222|    }
