31|        'unit_type' => ['label' => 'نوع واحد'],
32|        'county' => ['label' => 'شهرستان'],
33|        'parent_name' => ['label' => 'والد مستقیم'],
34|        'full_path' => ['label' => 'مسیر کامل'],
35|        'depth' => ['label' => 'سطح'],
36|        'status' => ['label' => 'وضعیت'],
37|    ];
38|
39|    /** @var array<int, string> */
40|    protected array $columns = ['id', 'name', 'unit_type', 'county', 'parent_name', 'full_path', 'depth', 'status'];
41|
42|    /** @var Collection<int, Unit> */
43|    protected Collection $units;
44|
45|    /**
46|     * Pre-resolved hierarchy metadata per unit id, built by the controller in
47|     * one pass so mapping a row never walks parents (and never N+1s).
48|     *
49|     * @var array<int, array{path: string, depth: int, parent_name: string}>
50|     */
51|    protected array $hierarchy;
52|
53|    /**
54|     * @param  Collection<int, Unit>  $units  depth-first ordered (parents before children)
55|     * @param  array<int, array{path: string, depth: int, parent_name: string}>  $hierarchy
56|     */
57|    public function __construct(Collection $units, array $hierarchy)
58|    {
59|        $this->units = $units;
60|        $this->hierarchy = $hierarchy;
61|    }
