38|    /**
39|     * Chunked export for large datasets — processes records in batches of $chunkSize
40|     * to avoid loading the entire result set into memory at once.
41|     */
42|    public function chunkCollection(): Collection
43|    {
44|        $chunk = $this->query
45|            ->with('user.person:id,n_code,f_name,l_name')
46|            ->where('id', '>', $this->lastId)
47|            ->orderBy('id')
48|            ->take($this->chunkSize)
49|            ->get();
50|
51|        if ($chunk->isNotEmpty()) {
52|            $this->lastId = $chunk->last()->id;
53|        }
54|
