3|namespace App\Console\Commands;
4|
5|use App\Models\DailyReport;
6|use App\Models\Unit;
7|use App\Services\AccessService;
8|use Illuminate\Console\Command;
9|
10|class GenerateDailyReports extends Command
11|{
12|    protected $signature = 'reports:generate-daily {--unit= : فقط برای یک واحد خاص} {--dry-run : فقط نمایش، بدون ذخیره}';
13|
14|    protected $description = 'Generate daily reports for all units (or one unit via --unit)';
15|
16|    public function handle(AccessService $access): int
17|    {
18|        $dryRun = (bool) $this->option('dry-run');
19|        $unitFilter = $this->option('unit');
20|
21|        $this->info('Generating daily reports...');
22|
23|        // Without --unit the scope is org-wide: the scheduler has no actor,
24|        // so accessibleUnitIds() is always `[]` there and the command would
25|        // exit 0 having written nothing (issue #836).
26|        $unitIds = $unitFilter
27|            ? [(int) $unitFilter]
28|            : $access->allUnitIds();
29|
30|        if (empty($unitIds)) {
31|            $this->warn('  No units found — nothing to report.');
32|            $this->info('Daily report generation complete.');
33|
34|            return 0;
35|        }
36|
37|        $this->line('  Scoped to '.count($unitIds).' unit(s).');
38|
39|        $today = now()->toDateString();
40|        $created = 0;
41|
42|        foreach ($unitIds as $unitId) {
43|            $unit = Unit::find($unitId);
44|            if (! $unit) {
45|                continue;
46|            }
47|
48|            $openTickets = $unit->tickets()->where('status', '!=', 'completed')->count();
49|            $openTodos = $unit->todos()->where('is_completed', false)->count();
50|
51|            $summary = "Unit {$unit->name}: {$openTickets} open tickets, {$openTodos} open todos.";
52|
53|            if ($dryRun) {
54|                $this->line("  [dry-run] {$summary}");
55|
56|                continue;
57|            }
58|
59|            if (DailyReport::where('unit_id', $unitId)->where('report_date', $today)->exists()) {
60|                continue;
61|            }
62|
63|            DailyReport::create([
64|                'unit_id' => $unitId,
65|                'report_date' => $today,
66|                'summary' => $summary,
67|                'payload' => [
68|                    'open_tickets' => $openTickets,
69|                    'open_todos' => $openTodos,
70|                ],
71|            ]);
72|
73|            $created++;
74|        }
75|
76|        $this->line("  Generated {$created} daily report(s).");
77|        $this->info('Daily report generation complete.');
78|
79|        return 0;
80|    }
