3|use App\Models\Todo;
4|use App\Services\AccessService;
5|use App\Services\DailySeries;
6|use Carbon\Carbon;
7|use Livewire\Component;
8|use Morilog\Jalali\Jalalian;
9|
10|return new class extends Component
11|{
12|    public string $dateFrom = '';
13|
14|    public string $dateTo = '';
15|
16|    public ?int $selectedUnitId = null;
17|
18|    public ?string $statusFilter = null; // completed, pending, overdue, null=all
19|
20|    public bool $showHelpModal = false;
21|
22|    /** Issue #819 — see the dashboard's `emptyScope` banner for the rationale. */
23|    public bool $emptyScope = false;
24|
25|    public function mount(): void
26|    {
27|        $this->dateFrom = Jalalian::fromCarbon(now()->subDays(30))->format('Y/m/d');
28|        $this->dateTo = Jalalian::fromCarbon(now()->addDays(30))->format('Y/m/d');
29|
30|        $this->emptyScope = app(AccessService::class)->accessibleUnitIds() === [];
31|    }
32|
33|    private function parseJalaliDate(?string $date, bool $endOfDay = false): ?Carbon
34|    {
35|        if (empty($date)) {
36|            return null;
37|        }
38|        try {
39|            $carbon = Jalalian::fromFormat('Y/m/d', $date)->toCarbon();
40|
41|            return $endOfDay ? $carbon->endOfDay() : $carbon->startOfDay();
42|        } catch (\Throwable) {
43|            return null;
44|        }
45|    }
46|
47|    /**
48|     * The chosen from..to range as Carbon bounds, or null when either end is
49|     * missing/invalid — in which case the daily series has no window to fill.
50|     *
51|     * @return array{0: Carbon, 1: Carbon}|null
52|     */
53|    private function dateRange(): ?array
54|    {
55|        $from = $this->parseJalaliDate($this->dateFrom);
56|        $to = $this->parseJalaliDate($this->dateTo, endOfDay: true);
57|
58|        if (! $from || ! $to || $from->gt($to)) {
59|            return null;
60|        }
61|
62|        return [$from, $to];
63|    }
64|
65|    public function chartPayload(): array
66|    {
67|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
68|
69|        // Issue #819: unconditional scope predicate. `whereIn()` at the top level
70|        // would degrade the builder to Query\Builder for `(clone $query)->with()`,
71|        // so the predicate goes inside a closure — still unconditional, still
72|        // fail-closed on an empty scope (`[]` compiles to `0 = 1`).
73|        $query = Todo::query()
74|            ->where(function ($q) use ($accessibleIds) {
75|                $q->whereIn('unit_id', $accessibleIds);
76|            })
77|            ->when($this->selectedUnitId, fn ($q) => $q->where('unit_id', $this->selectedUnitId));
78|
79|        if ($from = $this->parseJalaliDate($this->dateFrom)) {
80|            $query->where('start_at', '>=', $from);
81|        }
82|        if ($to = $this->parseJalaliDate($this->dateTo, endOfDay: true)) {
83|            $query->where('end_at', '<=', $to);
84|        }
85|
86|        $now = now();
87|        $completed = (clone $query)->where('is_completed', true)->count();
88|        $pending = (clone $query)->where('is_completed', false)->count();
89|        $overdue = (clone $query)->where('is_completed', false)
90|            ->whereNotNull('end_at')->where('end_at', '<', $now)->count();
91|
92|        $byUnit = Todo::selectRaw('COALESCE(units.name, ?) as unit_name, COUNT(*) as count', ['نامشخص'])
93|            ->whereIn('todos.unit_id', $accessibleIds)
94|            ->when($this->selectedUnitId, fn ($q) => $q->where('todos.unit_id', $this->selectedUnitId))
95|            ->leftJoin('units', 'todos.unit_id', '=', 'units.id')
96|            ->groupBy('unit_name')
97|            ->pluck('count', 'unit_name')
98|            ->toArray();
99|
100|        // Issue #736: materialise every day in the chosen range, zeros included,
101|        // so a day with no todos is a zero rather than a missing column. The
102|        // filtered $query is reused, so unit/status/date filters still apply.
103|        $range = $this->dateRange();
104|        $byDay = $range
105|            ? array_map(
106|                fn (array $row) => [
107|                    'day' => Jalalian::fromCarbon(Carbon::parse($row['day']))->format('Y/m/d'),
108|                    'count' => $row['count'],
109|                ],
110|                DailySeries::between($range[0], $range[1])->counts(clone $query, 'start_at')
111|            )
112|            : [];
113|
114|        $byStatus = [
115|            'تکمیل شده' => $completed,
116|            'در انتظار' => $pending,
117|            'سررسید گذشته' => $overdue,
118|        ];
119|
120|        $items = (clone $query)
121|            ->when($this->statusFilter === 'completed', fn ($q) => $q->where('is_completed', true))
122|            ->when($this->statusFilter === 'pending', fn ($q) => $q->where('is_completed', false)->where(fn ($q) => $q->whereNull('end_at')->orWhere('end_at', '>=', $now)))
123|            ->when($this->statusFilter === 'overdue', fn ($q) => $q->where('is_completed', false)->whereNotNull('end_at')->where('end_at', '<', $now))
124|            ->with('unit:id,name')
125|            ->orderBy('start_at', 'desc')
126|            ->get()
127|            ->map(fn ($t) => [
128|                'id' => $t->id,
129|                'title' => $t->title,
130|                'unit' => $t->unit?->name ?? '—',
131|                'start' => $t->start_at ? Jalalian::fromCarbon(Carbon::parse($t->start_at))->format('Y/m/d') : '—',
132|                'end' => $t->end_at ? Jalalian::fromCarbon(Carbon::parse($t->end_at))->format('Y/m/d') : '—',
133|                'completed' => $t->is_completed,
134|                'is_overdue' => ! $t->is_completed && $t->end_at && $t->end_at < $now,
135|            ])
136|            ->toArray();
137|
138|        return [
139|            'completed' => $completed,
140|            'pending' => $pending,
141|            'overdue' => $overdue,
142|            'byUnit' => $byUnit,
143|            'byDay' => $byDay,
144|            'byStatus' => $byStatus,
145|            'items' => $items,
146|        ];
147|    }
148|
149|    public function getAccessibleUnitsProperty()
150|    {
151|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
152|
153|        return \App\Models\Unit::whereIn('id', $accessibleIds)->get();
154|    }
155|}; ?>
