297|        if (attempts > 100) { console.error('Highcharts failed to load'); return; }
298|        setTimeout(() => waitForHighcharts(callback, attempts + 1), 50);
299|    }
300|
301|    function destroyChart(id) {
302|        const container = document.getElementById(id);
303|        if (!container || typeof Highcharts === 'undefined') return;
304|        const existing = Highcharts.charts?.find(c => c && c.renderTo === container);
305|        if (existing) existing.destroy();
306|        container.innerHTML = '';
307|    }
