158|<script>
159|    // Palettes keyed by data-theme (see x-theme-selector: fantasy light / dark).
160|    // Bars, axis text and grid lines must follow the active DaisyUI theme.
161|    const HR_CHART_PALETTES = {
162|        fantasy: {
163|            colors: ['#6366f1', '#10b981', '#0ea5e9', '#f59e0b'],
164|            text: '#3f3f46',
165|            grid: '#e4e4e7'
166|        },
167|        dark: {
168|            colors: ['#a78bfa', '#34d399', '#38bdf8', '#fbbf24'],
169|            text: '#d4d4d8',
170|            grid: '#3f3f46'
171|        }
172|    };
173|
174|    function hrPalette() {
175|        return HR_CHART_PALETTES[document.documentElement.dataset.theme] ?? HR_CHART_PALETTES.fantasy;
176|    }
177|
178|    function destroyHrChart(id) {
179|        const container = document.getElementById(id);
180|        if (!container || typeof Highcharts === 'undefined') return;
181|        const existing = Highcharts.charts?.find(c => c && c.renderTo === container);
182|        if (existing) existing.destroy();
183|        container.innerHTML = '';
184|    }
185|
186|    function renderHrBar(id, rows, color, palette) {
187|        destroyHrChart(id);
188|        const data = (rows || [])
189|            .slice()
190|            .sort((a, b) => b.total - a.total)
191|            .map(r => ({ name: r.name, y: r.total }));
192|
193|        if (!data.length || typeof Highcharts === 'undefined') return;
194|
195|        Highcharts.chart(id, {
196|            chart: { type: 'bar' },
197|            title: { text: '' },
198|            xAxis: {
199|                type: 'category',
200|                labels: { style: { fontSize: '12px', color: palette.text } }
201|            },
202|            yAxis: {
203|                title: { text: 'تعداد', style: { color: palette.text } },
204|                labels: { style: { color: palette.text } },
205|                gridLineColor: palette.grid,
206|                allowDecimals: false,
207|                minRange: 1
208|            },
209|            legend: { enabled: false },
210|            credits: { enabled: false },
211|            tooltip: { style: { color: palette.text } },
212|            series: [{
213|                name: 'تعداد پرسنل',
214|                data: data,
215|                color: color,
216|                dataLabels: {
217|                    enabled: true,
218|                    align: 'left',
219|                    format: '{y}',
220|                    style: { color: palette.text }
221|                }
222|            }]
223|        });
