233|        renderHrBar('hrChartBySemat', hrChartData.bySemat, palette.colors[1], palette);
234|        renderHrBar('hrChartByTahsil', hrChartData.byTahsil, palette.colors[2], palette);
235|        renderHrBar('hrChartByEstekhdam', hrChartData.byEstekhdam, palette.colors[3], palette);
236|    }
237|
238|    async function renderHrCharts() {
239|        hrChartData = await $wire.chartPayload();
240|        paintHrCharts();
241|    }
242|
243|    function waitForHighcharts(fn) {
244|        if (typeof Highcharts !== 'undefined') return fn();
245|        setTimeout(() => waitForHighcharts(fn), 100);
