296|    /**
297|     * Zabbix sync state for the status banner (#740).
298|     *
299|     * The traffic charts can only be showing fresh numbers when the LAST
300|     * run succeeded inside the 5-minute cache TTL — this separates "sync
301|     * سالم" from "reading stale cache" (and from a job that stopped running
302|     * entirely), which the cache alone could never tell apart.
303|     *
304|     * Reads the row through the DB facade so the import block (and with it
305|     * the anonymous class line the PHPStan baseline is keyed on) stays
306|     * untouched.
307|     *
308|     * @return array{state: string, time: string, failures: int, cache: bool}
309|     */
310|    public function getZabbixSyncStatusProperty(): array
311|    {
312|        $latest = DB::table('zabbix_sync_logs')->orderByDesc('id')->first();
313|
314|        if ($latest === null) {
315|            return ['state' => 'unknown', 'time' => '', 'failures' => 0, 'cache' => false];
316|        }
317|
318|        $ranAt = strtotime((string) $latest->ran_at);
319|        $time = $ranAt !== false ? date('H:i', $ranAt) : '';
320|        $cache = Cache::has('zabbix_traffic_data');
321|
322|        if ($latest->success) {
323|            return [
324|                // Fresh = last success inside the 5-minute cache TTL.
325|                'state' => ($ranAt !== false && $ranAt > time() - 300) ? 'ok' : 'stale',
326|                'time' => $time,
327|                'failures' => 0,
328|                'cache' => $cache,
329|            ];
330|        }
331|
332|        return [
333|            'state' => 'failing',
334|            'time' => $time,
335|            'failures' => (int) $latest->consecutive_failures,
336|            'cache' => $cache,
337|        ];
338|    }
