246|
247|        if (empty($ids)) {
248|            return collect();
249|        }
250|
251|        // Cache by sorted IDs to get consistent results regardless of input order
252|        $cache = app(CacheInvalidationServiceInterface::class);
253|        $version = $cache->getVersion('unit_hierarchy');
254|        $sorted = array_map('strval', $ids);
255|        sort($sorted, SORT_STRING);
256|        $cacheKey = 'unit_descendants:v'.$version.':'.md5(implode(',', $sorted));
257|
258|        return Cache::remember(
259|            $cacheKey,
